def liftFiniteCoefficients {n : ℕ} (c : FiniteMultiIndex n → ℂ)
    (β : FiniteMultiIndex (n + 1)) : ℂ :=
  if β (Fin.last n) = 0 then c (fun j => β j.castSucc) else 0

